  @Description_a0fc3c29696a = N'Search for the Deal form''s account picker: sales accounts whose name, legal name or website domain starts with the term.'
SET
  @SQL_a0fc3c29696a = N'-- Deal Account picker (bc-aidp-next-golive#372). Common''s "Common: Party Lookup Organizations" restricted
-- to organizations that have a SalesAccount row: Deal.AccountID points at SalesAccount, whose ID is the
-- Organization''s ID (IsA), so an organization without one cannot be stored.
--
-- Result contract shared by every party lookup query: ID, Name, Detail; parameters Term (required) and
-- Domain (optional, set by the picker when the term looks like a web address).
-- Prefix matches on indexed base columns only, TOP 20, no view, no count. sqlLikeBegins escapes %, _ and [ (and drops a trailing %).
SELECT TOP 20
    o.ID,
    o.Name,
    o.WebsiteDomain AS Detail
FROM [__mj_BizAppsCommon].Organization o
WHERE (
       o.Name      LIKE {{ Term | sqlLikeBegins }}
    OR o.LegalName LIKE {{ Term | sqlLikeBegins }}
    {% if Domain %}
    OR o.WebsiteDomain LIKE {{ Domain | sqlLikeBegins }}
    {% endif %}
)
  AND EXISTS (SELECT 1 FROM [__mj_BizAppsSales].SalesAccount sa WHERE sa.ID = o.ID)
ORDER BY o.Name, o.ID
'
SET
  @TechnicalDescription_a0fc3c29696a = N'Grain: Organization with a SalesAccount row (the IsA subtype Deal.AccountID references; subtype ID = Organization ID). Party lookup contract (bc-aidp-next-golive#372): columns ID, Name, Detail (WebsiteDomain); parameters Term (required) and Domain (optional; matched against Organization.WebsiteDomain). Prefix LIKE on indexed base columns, TOP 20 ordered by Name, no view and no count. Called by bizapps-party-field from @mj-biz-apps/common-ng.'
