@IsMaterialized_45f842a5b324 BIT
SET
  @ID_45f842a5b324 = '91CA1AC4-2598-4C64-B095-40467BADE081'
SET
  @Name_45f842a5b324 = N'Sales: Party Lookup Contacts'
SET
  @CategoryID_45f842a5b324 = '5A1E5000-0000-4000-A000-000000000001'
SET
  @UserQuestion_45f842a5b324 = N'Which sales contacts start with what I have typed?'
SET
  @Description_45f842a5b324 = N'Search for the Deal form''s contact pickers: sales contacts whose last name, display name, email or email domain starts with the term.'
SET
  @SQL_45f842a5b324 = N'-- Deal Primary/Billing Contact picker (bc-aidp-next-golive#372). Common''s "Common: Party Lookup People"
-- restricted to people who have a SalesContact row: Deal''s contact FKs point at SalesContact, whose ID is
-- the Person''s ID (IsA), so a person without one cannot be stored.
--
-- Result contract shared by every party lookup query: ID, Name, Detail; parameters Term (required) and
-- Domain (optional, set by the picker when the term looks like part of an email address).
-- Prefix matches on indexed base columns only, TOP 20, no view, no count: this is what keeps it under a
-- second on a party file of a million people. sqlLikeBegins escapes %, _ and [ (and drops a trailing %).
SELECT TOP 20
    p.ID,
    p.DisplayName AS Name,
    p.Email       AS Detail
FROM [__mj_BizAppsCommon].Person p
WHERE (
       p.LastName    LIKE {{ Term | sqlLikeBegins }}
    OR p.DisplayName LIKE {{ Term | sqlLikeBegins }}
    OR p.Email       LIKE {{ Term | sqlLikeBegins }}
    {% if Domain %}
    OR p.EmailDomain LIKE {{ Domain | sqlLikeBegins }}
    {% endif %}
)
  AND EXISTS (SELECT 1 FROM [__mj_BizAppsSales].SalesContact sc WHERE sc.ID = p.ID)
ORDER BY p.DisplayName, p.ID
'
SET
  @TechnicalDescription_45f842a5b324 = N'Grain: Person with a SalesContact row (the IsA subtype the Deal''s contact FKs reference; subtype ID = Person ID). Party lookup contract (bc-aidp-next-golive#372): columns ID, Name (DisplayName), Detail (Email); parameters Term (required) and Domain (optional; matched against Person.EmailDomain). Prefix LIKE on indexed base columns, TOP 20 ordered by DisplayName, no view and no count. Called by bizapps-party-field from @mj-biz-apps/common-ng.'
SET
  @Status_45f842a5b324 = N'Approved'
SET
  @QualityRank_45f842a5b324 = 8
SET
  @ExecutionCostRank_45f842a5b324 = 1
SET
  @UsesTemplate_45f842a5b324 = 1
SET
  @AuditQueryRuns_45f842a5b324 = 0
